//! Code generation from idlproj.yml: Xcode projects, xtool/SwiftPM manifests
//! and compile_commands.json for clangd / sourcekit-lsp.
const std = @import("std");
const diag = @import("diag.zig");
const fsutil = @import("fsutil.zig");
const config = @import("config.zig");
const pbxproj = @import("pbxproj.zig");
const Toolchain = @import("toolchain.zig").Toolchain;

const Allocator = std.mem.Allocator;
const Target = config.Target;

pub const marker = "Generated by idl from idlproj.yml";

/// Write a generated file, refusing to clobber hand-written files (no marker).
pub fn writeGenerated(a: Allocator, path: []const u8, content: []const u8) !bool {
    if (fsutil.kind(path) == .symlink) return diag.fail("refusing to write through symlink: {s}", .{path});
    if (std.fs.cwd().readFileAlloc(a, path, 16 << 20)) |old| {
        if (std.mem.indexOf(u8, old, marker) == null)
            return diag.fail("{s} exists and was not generated by idl; delete it or disable its generation in idlproj.yml", .{path});
    } else |_| {}
    return fsutil.writeIfChanged(a, path, content);
}

fn report(path: []const u8, changed: bool) void {
    diag.info("  GEN  {s}{s}", .{ path, if (changed) "" else " (unchanged)" });
}

// ------------------------------------------------------------------ xtool

pub fn xtoolYml(a: Allocator, t: Target) ![]const u8 {
    var b = std.ArrayList(u8).init(a);
    const w = b.writer();
    try w.print("# " ++ marker ++ "; edit idlproj.yml instead.\nversion: 1\nbundleID: {s}\nproduct: {s}\ninfoPath: {s}\n", .{ t.bundle_id, t.name, t.info_plist });
    if (t.entitlements) |e| try w.print("entitlementsPath: {s}\n", .{e});
    return b.items;
}

fn swiftString(w: anytype, s: []const u8) !void {
    try w.writeByte('"');
    for (s) |c| switch (c) {
        '\\', '"' => try w.print("\\{c}", .{c}),
        '\n' => try w.writeAll("\\n"),
        else => try w.writeByte(c),
    };
    try w.writeByte('"');
}

fn swiftStringList(w: anytype, items: []const []const u8) !void {
    try w.writeByte('[');
    for (items, 0..) |item, i| {
        if (i > 0) try w.writeAll(", ");
        try swiftString(w, item);
    }
    try w.writeByte(']');
}

pub fn packageSwift(a: Allocator, t: Target) ![]const u8 {
    if (t.sources.len != 1) return diag.fail("target '{s}': xtool builds need exactly one source directory (the SwiftPM target path)", .{t.name});
    const files = try fsutil.discover(a, t.dir, t.sources, "source");
    var has_swift = false;
    var has_c = false;
    var has_objc = false;
    for (files) |f| {
        const lang = Toolchain.langOf(f) orelse continue;
        switch (lang) {
            .swift => has_swift = true,
            .objc, .objcxx => {
                has_c = true;
                has_objc = true;
            },
            else => has_c = true,
        }
    }
    if (has_swift and has_c) return diag.fail("target '{s}': SwiftPM cannot mix Swift and C-family sources in one target; use the direct builder", .{t.name});
    if (!has_swift and !has_c) return diag.fail("target '{s}': no sources found in {s}", .{ t.name, t.sources[0] });
    const src = try fsutil.normalizeRelative(a, t.sources[0]);

    var b = std.ArrayList(u8).init(a);
    const w = b.writer();
    try w.writeAll("// swift-tools-version: 6.0\n// " ++ marker ++ "; edit idlproj.yml instead.\nimport PackageDescription\n\nlet package = Package(\n    name: ");
    try swiftString(w, t.name);
    try w.writeAll(",\n    platforms: [.iOS(");
    try swiftString(w, t.min_ios);
    try w.writeAll(")],\n    products: [.library(name: ");
    try swiftString(w, t.name);
    try w.writeAll(", targets: [");
    try swiftString(w, t.name);
    try w.writeAll("])],\n    targets: [\n        .target(\n            name: ");
    try swiftString(w, t.name);
    try w.writeAll(",\n            path: ");
    try swiftString(w, src);
    try w.writeAll(",\n");
    if (has_c and fsutil.kind(try fsutil.join(a, t.dir, try std.fmt.allocPrint(a, "{s}/include", .{src}))) == .dir)
        try w.writeAll("            publicHeadersPath: \"include\",\n");
    if (has_c) {
        var settings = std.ArrayList([]const u8).init(a);
        var flags = std.ArrayList([]const u8).init(a);
        if (has_objc) try flags.append("-fobjc-arc");
        try flags.appendSlice(t.cflags);
        if (flags.items.len > 0) {
            var fb = std.ArrayList(u8).init(a);
            try fb.appendSlice(".unsafeFlags(");
            try swiftStringList(fb.writer(), flags.items);
            try fb.append(')');
            try settings.append(fb.items);
        }
        for (t.defines) |d| {
            var db = std.ArrayList(u8).init(a);
            const eq = std.mem.indexOfScalar(u8, d, '=');
            try db.appendSlice(".define(");
            try swiftString(db.writer(), if (eq) |i| d[0..i] else d);
            if (eq) |i| {
                try db.appendSlice(", to: ");
                try swiftString(db.writer(), d[i + 1 ..]);
            }
            try db.append(')');
            try settings.append(db.items);
        }
        if (settings.items.len > 0) try w.print("            cSettings: [{s}],\n", .{try std.mem.join(a, ", ", settings.items)});
    } else {
        var settings = std.ArrayList([]const u8).init(a);
        for (t.defines) |d| {
            var db = std.ArrayList(u8).init(a);
            try db.appendSlice(".define(");
            try swiftString(db.writer(), d);
            try db.append(')');
            try settings.append(db.items);
        }
        if (t.swiftflags.len > 0) {
            var fb = std.ArrayList(u8).init(a);
            try fb.appendSlice(".unsafeFlags(");
            try swiftStringList(fb.writer(), t.swiftflags);
            try fb.append(')');
            try settings.append(fb.items);
        }
        if (settings.items.len > 0) try w.print("            swiftSettings: [{s}],\n", .{try std.mem.join(a, ", ", settings.items)});
    }
    var link = std.ArrayList([]const u8).init(a);
    for (t.frameworks) |f| {
        var lb = std.ArrayList(u8).init(a);
        try lb.appendSlice(".linkedFramework(");
        try swiftString(lb.writer(), if (std.mem.endsWith(u8, f, ".framework")) f[0 .. f.len - 10] else f);
        try lb.append(')');
        try link.append(lb.items);
    }
    for (t.libraries) |l| {
        var lb = std.ArrayList(u8).init(a);
        try lb.appendSlice(".linkedLibrary(");
        try swiftString(lb.writer(), l);
        try lb.append(')');
        try link.append(lb.items);
    }
    if (t.ldflags.len > 0) {
        var lb = std.ArrayList(u8).init(a);
        var xl = std.ArrayList([]const u8).init(a);
        for (t.ldflags) |l| try xl.appendSlice(&.{ "-Xlinker", l });
        try lb.appendSlice(".unsafeFlags(");
        try swiftStringList(lb.writer(), xl.items);
        try lb.append(')');
        try link.append(lb.items);
    }
    if (link.items.len > 0) try w.print("            linkerSettings: [{s}]\n", .{try std.mem.join(a, ", ", link.items)});
    try w.writeAll("        ),\n    ]\n)\n");
    return b.items;
}

pub fn genXtool(a: Allocator, t: Target) !void {
    const yml = try t.path(a, "xtool.yml");
    report(yml, try writeGenerated(a, yml, try xtoolYml(a, t)));
    if (t.package_swift) {
        const pkg = try t.path(a, "Package.swift");
        report(pkg, try writeGenerated(a, pkg, try packageSwift(a, t)));
    }
}

// -------------------------------------------------------- compile_commands

const CompileCommand = struct {
    directory: []const u8,
    file: []const u8,
    arguments: []const []const u8,
    output: []const u8,
};

pub fn compileCommands(a: Allocator, tc: *const Toolchain, t: Target, sources: []const []const u8) ![]const u8 {
    const build_dir = try t.buildPath(a);
    const module_cache = try std.fs.path.join(a, &.{ build_dir, "ModuleCache" });
    var cmds = std.ArrayList(CompileCommand).init(a);
    var swift_files = std.ArrayList([]const u8).init(a);
    for (sources) |rel| {
        const lang = Toolchain.langOf(rel) orelse continue;
        const file = try t.path(a, rel);
        if (lang == .swift) {
            try swift_files.append(file);
            continue;
        }
        const obj = try std.fmt.allocPrint(a, "{s}/obj/{s}.o", .{ build_dir, rel });
        var argv = std.ArrayList([]const u8).init(a);
        try argv.append(if (lang == .cxx or lang == .objcxx) tc.cxx orelse tc.cfg.cxx else tc.cc orelse tc.cfg.cc);
        try argv.appendSlice(try tc.cflags(t, lang, module_cache));
        try argv.appendSlice(&.{ "-c", file, "-o", obj });
        try cmds.append(.{ .directory = t.dir, .file = file, .arguments = argv.items, .output = obj });
    }
    // sourcekit-lsp reads one entry per Swift file carrying the full module invocation.
    for (swift_files.items) |file| {
        var argv = std.ArrayList([]const u8).init(a);
        try argv.append(tc.swiftc orelse tc.cfg.swiftc);
        try argv.appendSlice(try tc.swiftflags(t, module_cache));
        try argv.appendSlice(swift_files.items);
        try cmds.append(.{ .directory = t.dir, .file = file, .arguments = argv.items, .output = try std.fmt.allocPrint(a, "{s}/{s}", .{ build_dir, t.name }) });
    }
    var out = std.ArrayList(u8).init(a);
    try std.json.stringify(cmds.items, .{ .whitespace = .indent_2 }, out.writer());
    try out.append('\n');
    return out.items;
}

// ------------------------------------------------------------------- all

pub const Options = struct {
    xcodeproj: bool = true,
    compile_commands: bool = true,
};

pub fn generate(a: Allocator, tc: *const Toolchain, t: Target, opts: Options) !void {
    if (t.builder == .xtool) try genXtool(a, t);
    if (opts.xcodeproj and t.xcodeproj) {
        const out = try std.fmt.allocPrint(a, "{s}/{s}.xcodeproj", .{ t.dir, t.name });
        report(try pbxproj.generateProject(a, t.manifest(), t.dir, out), true);
    }
    if (opts.compile_commands and t.compile_commands and t.builder == .direct) {
        try tc.require(false);
        const sources = try fsutil.discover(a, t.dir, t.sources, "source");
        const path = try t.path(a, "compile_commands.json");
        report(path, try fsutil.writeIfChanged(a, path, try compileCommands(a, tc, t, sources)));
    }
}

test "Package.swift for an Objective-C xtool target" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const a = arena.allocator();
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    try tmp.dir.makePath("Sources/App/include");
    try tmp.dir.writeFile(.{ .sub_path = "Sources/App/appmain.m", .data = "int main(){}" });
    const t: Target = .{
        .name = "App",
        .dir = try tmp.dir.realpathAlloc(a, "."),
        .bundle_id = "com.example.app",
        .builder = .xtool,
        .sources = &.{"Sources/App"},
        .frameworks = &.{"UIKit"},
        .info_plist = "xtool-support/Info.plist",
    };
    try std.testing.expectEqualStrings(
        \\// swift-tools-version: 6.0
        \\// Generated by idl from idlproj.yml; edit idlproj.yml instead.
        \\import PackageDescription
        \\
        \\let package = Package(
        \\    name: "App",
        \\    platforms: [.iOS("16.0")],
        \\    products: [.library(name: "App", targets: ["App"])],
        \\    targets: [
        \\        .target(
        \\            name: "App",
        \\            path: "Sources/App",
        \\            publicHeadersPath: "include",
        \\            cSettings: [.unsafeFlags(["-fobjc-arc"])],
        \\            linkerSettings: [.linkedFramework("UIKit")]
        \\        ),
        \\    ]
        \\)
        \\
    , try packageSwift(a, t));
    try std.testing.expectEqualStrings(
        \\# Generated by idl from idlproj.yml; edit idlproj.yml instead.
        \\version: 1
        \\bundleID: com.example.app
        \\product: App
        \\infoPath: xtool-support/Info.plist
        \\
    , try xtoolYml(a, t));
    // Hand-written files are never overwritten.
    const path = try std.fs.path.join(a, &.{ t.dir, "Package.swift" });
    try tmp.dir.writeFile(.{ .sub_path = "Package.swift", .data = "// mine\n" });
    try std.testing.expectError(error.Invalid, writeGenerated(a, path, "x"));
}
